mapper.select:


    inner join sys_user u on u.user_name = a.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    a.del_flag = '0'
    and a.code like concat('%', #{code}, '%')
    and a.origin_code like concat('%',
        #{originCode}, '%')

    and a.origin_date = #{originDate}
    and a.origin_data = #{originData}
    and a.type = #{type}
    and a.status = #{status}
    and a.auditor = #{auditor}
    and a.new_local = #{newLocal}
    and a.complete_state =
        #{completeState}



${params.dataScope}
